<template>
  <ChartMetricContainer
    class="w-full min-h-0 self-start"
    :title="props.title"
    :subtitle="props.subtitle"
    :collapsible="false"
    :loading="props.loading"
  >
    <template #headerAside>
      <div v-if="props.breakdownOptions.length" class="w-52">
        <Select
          :model-value="props.breakdownBy"
          :options="props.breakdownOptions"
          @update:model-value="handleBreakdownChange"
        />
      </div>
    </template>
    <template #headerExport>
      <FooterExport
        v-if="enableExport && !props.loading"
        variant="inline"
        :loading="exportLoading"
        @export="handleExport"
      />
    </template>
    <div
      class="flex min-h-0 w-full shrink-0 flex-col font-[family-name:Inter,ui-sans-serif,system-ui,sans-serif]"
    >
      <div class="w-full shrink-0 flex min-h-0 flex-col">
        <section
          v-if="dataChart.labels && dataChart.labels.length"
          class="flex w-full shrink-0 flex-col gap-3"
        >
          <div
            class="chart-line-area flex h-[230px] w-full min-w-0 shrink-0 flex-col overflow-hidden"
          >
            <LineChart :data="dataChart" :theme="theme" />
          </div>
          <div
            v-if="props.showSummaryCards && channelTotalsCards.length"
            class="grid w-full gap-3 md:gap-4"
            :style="cardInfoGridStyle"
          >
            <CardInfo
              v-for="ch in channelTotalsCards"
              :key="ch.name"
              class="min-w-0"
              :color="ch.color"
              :title="ch.label"
              :value="`${ch.percentage}%`"
              :subvalue="`${useNumberFormat(ch.total)} ${props.unit}`"
            />
          </div>
        </section>

        <section
          v-else-if="props.showSummaryCards && channelTotals.length"
          class="flex w-full shrink-0 flex-col gap-4 sm:gap-6"
        >
          <div class="grid w-full gap-3 md:gap-4" :style="cardInfoGridStyle">
            <CardInfo
              v-for="ch in channelTotalsCards"
              :key="ch.name"
              class="min-w-0"
              :color="ch.color"
              :title="ch.label"
              :value="`${ch.percentage}%`"
              :subvalue="`${useNumberFormat(ch.total)} ${props.unit}`"
            />
          </div>
        </section>

        <section
          v-if="!channelTotals.length"
          class="flex min-h-[280px] flex-1 items-center justify-center"
        >
          <div class="max-w-[360px] px-4 text-center">
            <div
              class="mx-auto mb-5 inline-flex h-20 w-20 items-center justify-center rounded-[20px] bg-[var(--kiut-bg-empty-icon,rgba(139,92,246,0.12))] shadow-[var(--kiut-shadow-empty-icon,0_8px_24px_rgba(139,92,246,0.15))]"
            >
              <ChartBarIcon
                class="h-10 w-10 text-[var(--kiut-primary,#8b5cf6)]"
              />
            </div>
            <p
              class="mb-2 text-lg font-semibold tracking-tight text-[var(--kiut-text-primary,#171717)] dark:text-[var(--kiut-text-primary,#e5e5e5)]"
            >
              {{ props.emptyTitle }}
            </p>
            <p
              class="m-0 text-sm leading-relaxed text-[var(--kiut-text-secondary,#737373)] dark:text-[var(--kiut-text-secondary,#a3a3a3)]"
            >
              {{ props.emptyDescription }}
            </p>
          </div>
        </section>
        </div>
    </div>
  </ChartMetricContainer>
</template>

<script setup lang="ts">
import { ref, watch, computed, toRef } from "vue";
import moment from "moment";
import { ChartBarIcon } from "@heroicons/vue/24/outline";
import LineChart from "../../Line/ChartLine.vue";
import ChartMetricContainer from "../../Utils/ChartMetricContainer/ChartMetricContainer.vue";
import CardInfo from "../../Utils/CardInfo/CardInfo.vue";
import { FooterExport, type ExportFormat } from "../../Utils/FooterExport";
import { useNumberFormat } from "../../../../plugins/numberFormat";
import {
  useThemeDetection,
  type Theme,
} from "../../../../composables/useThemeDetection";
import Select, { type KiutSelectValue } from "../../../../components/Inputs/Select.vue";

const loaderBarHeights = [30, 50, 70, 50, 40];
const loaderDelays = [
  "",
  "delay-100",
  "delay-200",
  "delay-300",
  "delay-[400ms]",
];

interface ChannelsByDay {
  [date: string]: {
    [channel: string]: number;
  };
}

interface TotalByChannel {
  [channel: string]: number;
}

interface MetricsData {
  airline_name?: string;
  start_date?: string;
  end_date?: string;
  channels_by_day: ChannelsByDay;
  total_by_channel: TotalByChannel;
  total_conversations: number;
}

interface BreakdownOption {
  value: string;
  label: string;
}

const props = withDefaults(
  defineProps<{
    loading?: boolean;
    data?: MetricsData | null;
    theme?: Theme;
    enableExport?: boolean;
    exportLoading?: boolean;
    title?: string;
    subtitle?: string;
    unit?: string;
    totalConversations?: number;
    emptyTitle?: string;
    emptyDescription?: string;
    breakdownBy?: string;
    breakdownOptions?: BreakdownOption[];
    showSummaryCards?: boolean;
  }>(),
  {
    loading: false,
    data: null,
    theme: undefined,
    enableExport: false,
    exportLoading: false,
    title: "Conversations by Channel",
    subtitle: "Conversations sent by AI agents",
    unit: "msgs",
    totalConversations: undefined,
    emptyTitle: "No channel metrics data available",
    emptyDescription: "No channel data found for the selected period. Try adjusting the date range.",
    breakdownBy: "",
    breakdownOptions: () => [],
    showSummaryCards: true,
  },
);

const emit = defineEmits<{
  export: [format: ExportFormat];
  changeBreakdown: [value: string];
}>();

const handleExport = (format: ExportFormat) => {
  emit("export", format);
};

const handleBreakdownChange = (value: KiutSelectValue): void => {
  emit("changeBreakdown", String(value));
};

const theme = toRef(props, "theme");
const { isDark } = useThemeDetection(theme);

const channelColorMap: Record<string, string> = {
  wsp: "#25D366",
  whatsapp: "#25D366",
  voice: "#8b5cf6",
  sms: "#f59e0b",
  web_chat: "#06b6d4",
  email: "#ec4899",
  messenger: "#0084ff",
  telegram: "#0088cc",
  instagram: "#E4405F",
};
const fallbackColors = ["#3B82F6", "#10B981", "#F59E0B", "#8B5CF6", "#EC4899", "#06B6D4"];

const getChannelColor = (value: string): string => {
  const normalized = value.toLowerCase();
  const configuredColor = channelColorMap[normalized];
  if (configuredColor) return configuredColor;

  const hash = Array.from(normalized).reduce(
    (currentHash, character) => ((currentHash << 5) - currentHash + character.charCodeAt(0)) | 0,
    0,
  );
  return fallbackColors[Math.abs(hash) % fallbackColors.length];
};

const dataChart = ref<{ labels: string[]; datasets: any[] }>({
  labels: [],
  datasets: [],
});
const metricsData = computed<MetricsData>(
  () =>
    props.data ?? {
      channels_by_day: {},
      total_by_channel: {},
      total_conversations: 0,
    },
);

const channelTotals = computed(() => {
  const totalByChannel = metricsData.value.total_by_channel || {};
  const groupedTotal = Object.values(totalByChannel).reduce(
    (sum, v) => sum + v,
    0,
  );
  const grandTotal = props.totalConversations ?? groupedTotal;
  if (grandTotal === 0) return [];

  return Object.entries(totalByChannel)
    .sort(([, a], [, b]) => b - a)
    .map(([name, total]) => ({
      name,
      label: name.toUpperCase(),
      total,
      percentage: ((total / grandTotal) * 100).toFixed(1),
      color: getChannelColor(name),
    }));
});

const MAX_CARD_INFO_COLUMNS = 5;

const channelTotalsCards = computed(() =>
  channelTotals.value.slice(0, MAX_CARD_INFO_COLUMNS),
);

const cardInfoGridStyle = computed(() => {
  const cols = Math.min(channelTotalsCards.value.length, MAX_CARD_INFO_COLUMNS);
  if (cols <= 0) return undefined;
  return { gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` };
});

const processChartData = (data: MetricsData | null) => {
  if (!data || !data.channels_by_day) {
    dataChart.value = { labels: [], datasets: [] };
    return;
  }

  const daysData = data.channels_by_day;
  const labels = Object.keys(daysData).sort();

  if (labels.length === 0) {
    dataChart.value = { labels: [], datasets: [] };
    return;
  }

  const categoriesSet = new Set<string>();
  for (const dayData of Object.values(daysData)) {
    for (const category of Object.keys(dayData)) {
      categoriesSet.add(category);
    }
  }
  const categories = Array.from(categoriesSet);

  const datasets = categories.map((category) => {
    return {
      label: category.toUpperCase(),
      data: labels.map((date) => daysData[date]?.[category] || 0),
      borderColor: getChannelColor(category),
    };
  });

  dataChart.value = {
    labels: labels.map((date) => moment(date).format("MMM DD")),
    datasets,
  };
};

watch(
  () => props.data,
  (newData) => {
    processChartData(newData ?? null);
  },
  { deep: true, immediate: true },
);

defineExpose({ isDark });
</script>

<style scoped>
/* Coincide con ChartLine: 220px trazado + 10px banda de indicadores/leyenda */
.chart-line-area {
  position: relative;
  min-height: 0;
}
</style>
