<template>
  <ChartMetricContainer
    class="seller-metrics-root h-full min-h-0"
    title="Seller Metrics"
    subtitle="Sales performance and failure analysis"
    :default-open="initiallyOpen"
    :loading="props.loading"
  >
    <template #headerExport>
      <FooterExport
        v-if="enableExport && !props.loading"
        variant="inline"
        @export="handleExport"
        :loading="exportLoading"
      />
    </template>
    <div class="card-body">
      <!-- Sankey Flow Chart -->
      <section v-if="sankeyData.nodes.length > 0" class="chart-section">
        <div class="chart-wrapper">
          <SankeyChart
            :data="sankeyData"
            height="420px"
            :node-gap="16"
          />
        </div>
      </section>

      <!-- Empty State for Chart -->
      <section v-else class="empty-state">
        <div class="empty-state-content">
          <div class="empty-icon-wrapper">
            <svg
              class="empty-icon"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                stroke-linecap="round"
                stroke-linejoin="round"
                stroke-width="2"
                d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
          </div>
          <p class="empty-title">No sales data available</p>
          <p class="empty-description">
            No sales data found for the selected period. Try adjusting the date
            range.
          </p>
        </div>
      </section>

      <section class="seller-value-cards">
        <CardInfo
          class="seller-value-card"
          color="var(--kiut-success)"
          title="Total Sales Value"
          :value="totalSalesCardValue"
        />
        <template v-if="props.showPaymentMethodDetails">
          <CardInfo
            class="seller-value-card"
            color="var(--kiut-success)"
            title="Bank Transfer Value"
            :value="bankTransferCardValue"
          />
          <CardInfo
            class="seller-value-card"
            color="var(--kiut-success)"
            title="Cash Option Value"
            :value="cashOptionCardValue"
          />
        </template>
      </section>

      <!-- Table Data (chrome: Utils/Table) -->
      <section
        v-if="tableData && tableData.length > 0"
        class="seller-daily-section"
      >
        <div class="w-full min-w-0">
          <Table
            :columns="sellerTableColumns"
            :rows="sellerTableRows"
            :max-visible-rows="3"
            row-key="id"
          >
            <template #cell-date="{ row }">
              <span class="sl-cell font-medium">{{
                moment(String(row.date)).format("MMM DD")
              }}</span>
            </template>
            <template #cell-sellInitiated="{ row }">
              <span class="sl-cell text-center">{{
                useNumberFormat(Number(row.seller_conversations) || 0)
              }}</span>
            </template>
            <template #cell-sellStarted="{ row }">
              <span class="sl-cell text-center">{{
                formatValueWithPercentage(
                  sellerDayFromRow(row).sell_started_count,
                  sellerDayFromRow(row).seller_conversations ||
                    sellerDayFromRow(row).sell_started_count,
                )
              }}</span>
            </template>
            <template #cell-getQuote="{ row }">
              <span class="sl-cell text-center">{{
                formatValueWithPercentage(
                  sellerDayFromRow(row).sell_get_quote_count,
                  sellerDayFromRow(row).seller_conversations ||
                    sellerDayFromRow(row).sell_started_count,
                )
              }}</span>
            </template>
            <template #cell-bookingCreated="{ row }">
              <span class="sl-cell text-center">{{
                formatValueWithPercentage(
                  sellerDayFromRow(row).sell_booking_created_count,
                  sellerDayFromRow(row).seller_conversations ||
                    sellerDayFromRow(row).sell_started_count,
                )
              }}</span>
            </template>
            <template #cell-btValue="{ row }">
              <span class="sl-cell text-center success-value">
                <div
                  v-if="
                    Array.isArray(
                      sellerDayFromRow(row)
                        .daily_value_sell_success_bank_transfer,
                    ) &&
                    (
                      sellerDayFromRow(row)
                        .daily_value_sell_success_bank_transfer as CurrencyValue[]
                    ).length > 0
                  "
                  class="currency-cell-list"
                >
                  <span
                    v-for="item in sellerDayFromRow(row)
                      .daily_value_sell_success_bank_transfer as CurrencyValue[]"
                    :key="`${row.date}-bt-success-${item.currency}`"
                  >
                    {{ item.currency }}
                    {{ useCompactCurrencyFormat(item.total_value) }}
                  </span>
                </div>
                <span v-else class="empty-cell">-</span>
              </span>
            </template>
            <template #cell-btSuccess="{ row }">
              <span class="sl-cell text-center success-value">{{
                useNumberFormat(
                  Number(
                    sellerDayFromRow(row).sell_success_bank_transfer_count,
                  ) || 0,
                )
              }}</span>
            </template>
            <template #cell-coValue="{ row }">
              <span class="sl-cell text-center success-value">
                <div
                  v-if="
                    Array.isArray(
                      sellerDayFromRow(row).daily_value_sell_success_cash,
                    ) &&
                    (
                      sellerDayFromRow(row)
                        .daily_value_sell_success_cash as CurrencyValue[]
                    ).length > 0
                  "
                  class="currency-cell-list"
                >
                  <span
                    v-for="item in sellerDayFromRow(row)
                      .daily_value_sell_success_cash as CurrencyValue[]"
                    :key="`${row.date}-co-success-${item.currency}`"
                  >
                    {{ item.currency }}
                    {{ useCompactCurrencyFormat(item.total_value) }}
                  </span>
                </div>
                <span v-else class="empty-cell">-</span>
              </span>
            </template>
            <template #cell-cashSuccess="{ row }">
              <span class="sl-cell text-center success-value">{{
                useNumberFormat(
                  Number(sellerDayFromRow(row).sell_success_cash_count) || 0,
                )
              }}</span>
            </template>
            <template #cell-sellSuccess="{ row }">
              <span class="sl-cell text-center">{{
                formatValueWithPercentage(
                  sellerDayFromRow(row).sell_success_count,
                  sellerDayFromRow(row).seller_conversations ||
                    sellerDayFromRow(row).sell_started_count,
                )
              }}</span>
            </template>
            <template #cell-totalSalesValue="{ row }">
              <span class="sl-cell text-center success-value">
                <div
                  v-if="
                    Array.isArray(row.daily_value_sell_success) &&
                    row.daily_value_sell_success.length > 0
                  "
                  class="currency-cell-list"
                >
                  <span
                    v-for="item in row.daily_value_sell_success"
                    :key="`${row.date}-${item.currency}`"
                  >
                    {{ item.currency }}
                    {{ useCompactCurrencyFormat(item.total_value) }}
                  </span>
                </div>
                <span v-else>{{
                  formatCurrencyValue(
                    sellerDayFromRow(row).daily_value_sell_success,
                  )
                }}</span>
              </span>
            </template>
            <template #cell-failed="{ row }">
              <div
                v-if="(sellerDayFromRow(row).reasons || []).length > 0"
                class="failed-reasons"
              >
                <div
                  v-for="reason in sellerDayFromRow(row).reasons || []"
                  :key="reason.reason"
                  class="failed-reason-item"
                >
                  <span class="reason-name">{{ reason.reason }}:</span>
                  <span class="reason-count">{{ reason.failed_count }}</span>
                </div>
              </div>
              <div v-else class="empty-cell">-</div>
            </template>
          </Table>
        </div>
      </section>
    </div>
  </ChartMetricContainer>
</template>

<script setup lang="ts">
import { computed, toRef } from "vue";
import moment from "moment";
import SankeyChart from "../../Sankey/SankeyChart.vue";
import {
  formatSankeyLinkLabel,
  formatSankeyPercentage,
} from "../../Sankey/sankeyFormatters";
import ChartMetricContainer from "../../Utils/ChartMetricContainer/ChartMetricContainer.vue";
import { FooterExport, type ExportFormat } from "../../Utils/FooterExport";
import {
  useNumberFormat,
  useCurrencyFormat,
  useCompactCurrencyFormat,
} from "../../../../plugins/numberFormat";
import {
  useThemeDetection,
  type Theme,
} from "../../../../composables/useThemeDetection";
import Table, { type TableColumn } from "../../Utils/Table/Table.vue";
import CardInfo from "../../Utils/CardInfo/CardInfo.vue";
import {
  computeSellerFunnelBreakdown,
  mergeSellerDaysWithFailed,
  type CurrencyValue,
  type FailedData,
  type SellerData,
  type SellerDayData,
} from "./sellerFunnelMetrics";

function sellerDayFromRow(r: Record<string, unknown>): SellerDayData {
  return r as unknown as SellerDayData;
}

const props = withDefaults(
  defineProps<{
    sellerData?: SellerData;
    failedData?: FailedData;
    loading?: boolean;
    theme?: Theme;
    enableExport?: boolean;
    exportLoading?: boolean;
    initiallyOpen?: boolean;
    showPaymentMethodDetails?: boolean;
  }>(),
  {
    sellerData: () => ({
      total_seller_conversations: 0,
      total_sell_started: 0,
      total_sell_get_quote: 0,
      total_sell_booking_created: 0,
      total_sell_success: 0,
      total_value_sell_success: 0,
      seller_by_day: [],
    }),
    failedData: () => ({
      total_sell_failed: 0,
      failed_by_reason_by_day: [],
    }),
    loading: false,
    theme: undefined,
    enableExport: false,
    exportLoading: false,
    initiallyOpen: true,
    showPaymentMethodDetails: false,
  },
);

const emit = defineEmits<{
  export: [format: ExportFormat];
}>();

const handleExport = (format: ExportFormat) => {
  emit("export", format);
};

// Theme detection with prop fallback
const { isDark } = useThemeDetection(toRef(props, "theme"));

// Computed para combinar y ordenar los datos de la tabla
const tableData = computed(() => {
  if (!props.sellerData?.seller_by_day) return [];

  return mergeSellerDaysWithFailed(props.sellerData, props.failedData).sort(
    (a, b) => new Date(a.date).getTime() - new Date(b.date).getTime(),
  );
});

const sellerTableColumns = computed<TableColumn[]>(() => {
  const columns: TableColumn[] = [
    { key: "date", label: "Date", align: "center" },
    { key: "sellInitiated", label: "Initiated by agent", align: "center" },
    { key: "sellStarted", label: "Sell Started", align: "center" },
    { key: "getQuote", label: "Get Quote", align: "center" },
    { key: "bookingCreated", label: "Booking Created", align: "center" },
  ];

  if (props.showPaymentMethodDetails) {
    columns.push(
      { key: "btValue", label: "BT Success Value", align: "center" },
      { key: "btSuccess", label: "BT Success", align: "center" },
      { key: "coValue", label: "CO Success Value", align: "center" },
      { key: "cashSuccess", label: "Cash Success", align: "center" },
    );
  }

  columns.push(
    { key: "sellSuccess", label: "Sell Success", align: "center" },
    { key: "totalSalesValue", label: "Total Sales Value", align: "center" },
    { key: "failed", label: "Failed", align: "center" },
  );

  return columns;
});

const sellerTableRows = computed((): Record<string, unknown>[] =>
  tableData.value.map((row) => ({
    id: row.date,
    ...row,
  })),
);

const totalSalesByCurrency = computed(() =>
  Array.isArray(props.sellerData.total_value_sell_success)
    ? props.sellerData.total_value_sell_success
    : [],
);
const bankTransferByCurrency = computed(() =>
  Array.isArray(props.sellerData.total_value_sell_success_bank_transfer)
    ? props.sellerData.total_value_sell_success_bank_transfer
    : [],
);
const cashOptionByCurrency = computed(() =>
  Array.isArray(props.sellerData.total_value_sell_success_cash)
    ? props.sellerData.total_value_sell_success_cash
    : [],
);

const totalSalesCardValue = computed((): string => {
  const items = totalSalesByCurrency.value;
  if (items.length > 0) {
    return items
      .map(
        (item) =>
          `${item.currency} ${useCompactCurrencyFormat(item.total_value)}`,
      )
      .join(" · ");
  }
  return formatCurrencyValue(props.sellerData.total_value_sell_success);
});

function formatCurrencyBreakdownCard(items: CurrencyValue[]): string {
  if (items.length > 0) {
    return items
      .map(
        (item) =>
          `${item.currency} ${useCompactCurrencyFormat(item.total_value)}`,
      )
      .join(" · ");
  }
  return "—";
}

const bankTransferCardValue = computed((): string =>
  formatCurrencyBreakdownCard(bankTransferByCurrency.value),
);

const cashOptionCardValue = computed((): string =>
  formatCurrencyBreakdownCard(cashOptionByCurrency.value),
);

const humanizeFailureReason = (reason: string): string =>
  reason
    .replace(/_/g, " ")
    .replace(/\b\w/g, (char) => char.toUpperCase());

const formatFailureNodeLabel = (reason: string): string =>
  `Failed:\n${humanizeFailureReason(reason)}`;

const sankeyData = computed(() => {
  const funnel = computeSellerFunnelBreakdown(
    props.sellerData,
    props.failedData,
  );
  if (!funnel) return { nodes: [], links: [] };

  const {
    initiated: conversations,
    started,
    bookingCreated,
    successOnline,
    successBankTransfer,
    successCash,
    droppedBeforeSales,
    failedAtBooking,
    failedAtCompletion,
    failedByReasons,
  } = funnel;

  const nodes: {
    name: string;
    value: number;
    status?: "success" | "abandon" | "error";
    label?: string;
  }[] = [
    { name: "Initiated by agent", value: conversations, status: "success" },
    { name: "Sell Started", value: started, status: "success" },
    { name: "Booking Created", value: bookingCreated, status: "success" },
    { name: "Sell Success", value: successOnline, status: "success" },
  ];

  const links: {
    source: string;
    target: string;
    value: number;
    label: string;
  }[] = [];

  if (droppedBeforeSales > 0) {
    nodes.push({
      name: "Abandoned: No Response",
      value: droppedBeforeSales,
      status: "abandon",
    });
    links.push({
      source: "Initiated by agent",
      target: "Abandoned: No Response",
      value: droppedBeforeSales,
      label: formatSankeyLinkLabel(droppedBeforeSales, conversations),
    });
  }

  if (started > 0) {
    links.push({
      source: "Initiated by agent",
      target: "Sell Started",
      value: started,
      label: formatSankeyLinkLabel(started, conversations),
    });
  }

  if (bookingCreated > 0) {
    links.push({
      source: "Sell Started",
      target: "Booking Created",
      value: bookingCreated,
      label: formatSankeyLinkLabel(bookingCreated, conversations),
    });
  }

  if (successBankTransfer > 0) {
    nodes.push({
      name: "Bank Transfer",
      value: successBankTransfer,
      status: "success",
    });
    links.push({
      source: "Booking Created",
      target: "Bank Transfer",
      value: successBankTransfer,
      label: formatSankeyLinkLabel(successBankTransfer, conversations),
    });
  }

  if (successCash > 0) {
    nodes.push({
      name: "Cash Option",
      value: successCash,
      status: "success",
    });
    links.push({
      source: "Booking Created",
      target: "Cash Option",
      value: successCash,
      label: formatSankeyLinkLabel(successCash, conversations),
    });
  }

  if (successOnline > 0) {
    links.push({
      source: "Booking Created",
      target: "Sell Success",
      value: successOnline,
      label: formatSankeyLinkLabel(successOnline, conversations),
    });
  }

  if (failedAtCompletion > 0) {
    nodes.push({
      name: "Failed at Completion",
      value: failedAtCompletion,
      status: "error",
    });
    links.push({
      source: "Booking Created",
      target: "Failed at Completion",
      value: failedAtCompletion,
      label: formatSankeyLinkLabel(failedAtCompletion, conversations),
    });
  }

  if (failedAtBooking > 0) {
    nodes.push({
      name: "Failed at Booking",
      value: failedAtBooking,
      status: "error",
    });
    links.push({
      source: "Sell Started",
      target: "Failed at Booking",
      value: failedAtBooking,
      label: formatSankeyLinkLabel(failedAtBooking, conversations),
    });
  }

  if (Object.keys(failedByReasons).length > 0) {
    const totalFailedReasons = Object.values(failedByReasons).reduce(
      (sum, count) => sum + count,
      0,
    );
    const withoutReason = failedAtBooking - totalFailedReasons;

    Object.entries(failedByReasons)
      .filter(([, count]) => count > 0)
      .sort(([, a], [, b]) => b - a)
      .forEach(([reason, count]) => {
        const nodeName = `Failed: ${reason}`;
        nodes.push({
          name: nodeName,
          value: count,
          status: "error",
          label: formatFailureNodeLabel(reason),
        });
        links.push({
          source: "Failed at Booking",
          target: nodeName,
          value: count,
          label: formatSankeyLinkLabel(count, conversations),
        });
      });

    if (withoutReason > 0) {
      nodes.push({
        name: "Failed: Without Reason",
        value: withoutReason,
        status: "error",
        label: "Failed:\nWithout Reason",
      });
      links.push({
        source: "Failed at Booking",
        target: "Failed: Without Reason",
        value: withoutReason,
        label: formatSankeyLinkLabel(withoutReason, conversations),
      });
    }
  }

  return {
    nodes,
    links,
  };
});


const calculatePercentage = (value: number, total: number): string =>
  formatSankeyPercentage(value, total);

const formatValueWithPercentage = (value: number, total: number): string => {
  const formattedValue = useNumberFormat(value);
  const percentage = calculatePercentage(value, total);
  return `${formattedValue} (${percentage})`;
};

// Helper to extract total value from currency array or number
const getTotalValue = (value: number | CurrencyValue[] | undefined): number => {
  if (value === undefined || value === null) return 0;
  if (typeof value === "number") return value;
  if (Array.isArray(value)) {
    return value.reduce((sum, item) => sum + (item.total_value || 0), 0);
  }
  return 0;
};

// Format currency value handling both number and array formats
const formatCurrencyValue = (
  value: number | CurrencyValue[] | undefined,
): string => {
  return useCompactCurrencyFormat(getTotalValue(value));
};

// Expose isDark for potential use in templates
defineExpose({ isDark });
</script>

